// Keep the imported form as an offline design reference.
document.addEventListener("submit", (event) => {
  if (!(event.target instanceof HTMLFormElement)) return;
  event.preventDefault();
  event.stopImmediatePropagation();
  let status = event.target.querySelector("[data-reference-status]");
  if (!status) {
    status = document.createElement("p");
    status.dataset.referenceStatus = "";
    status.setAttribute("role", "status");
    event.target.append(status);
  }
  status.textContent = "Design reference. This form does not send information.";
}, true);

